<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { AdminReaderAccount, PasswordResetCredential } from '../../api/auth';
import AppButton from '../../ui/components/AppButton.vue';
export default defineComponent({name:'ReaderResetDialog',components:{AppButton},props:{account:{type:Object as PropType<AdminReaderAccount>,required:true},credential:{type:Object as PropType<PasswordResetCredential|null>,default:null},busy:Boolean,error:{type:String,default:''}},emits:['issue','close'],data(){return{copied:false}},methods:{async copy(){if(!this.credential)return;try{await navigator.clipboard.writeText(this.credential.token);this.copied=true}catch{this.copied=false}},formatExpiry(value:number){return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value*1000))}}});
</script>
<template><div class="overlay" @click.self="$emit('close')" @keydown.esc="$emit('close')"><section class="dialog" role="dialog" aria-modal="true" :aria-label="$t('account.readers.reset.title')"><header><div><p class="eyebrow">{{ $t('account.readers.reset.eyebrow') }}</p><h2>{{ account.username }}</h2></div><AppButton variant="quiet" :disabled="busy" @click="$emit('close')">{{ $t('account.readers.close') }}</AppButton></header><template v-if="credential"><p class="warning">{{ $t('account.readers.reset.once') }}</p><label><span>{{ $t('account.readers.reset.token') }}</span><textarea :value="credential.token" readonly spellcheck="false" /></label><p>{{ $t('account.readers.reset.expires',{time:formatExpiry(credential.expiresAt)}) }}</p><AppButton variant="secondary" @click="copy">{{ copied?$t('account.readers.reset.copied'):$t('account.readers.reset.copy') }}</AppButton></template><template v-else><p>{{ $t('account.readers.reset.description') }}</p><p class="warning">{{ $t('account.readers.reset.invalidates') }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><AppButton :busy="busy" @click="$emit('issue')">{{ busy?$t('account.readers.reset.issuing'):$t('account.readers.reset.issue') }}</AppButton></template></section></div></template>
<style scoped>.overlay{position:fixed;z-index:90;inset:0;display:flex;align-items:center;justify-content:center;padding:1rem;background:rgb(0 0 0/.42)}.dialog{width:min(34rem,100%);display:grid;gap:1rem;padding:1rem;border-radius:var(--radius-lg);background:var(--color-paper-raised)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem}h2,p{margin:0}h2{font:700 1.35rem var(--font-literary)}.eyebrow{color:var(--color-warm);font-size:.7rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.warning{padding:.7rem;border-radius:var(--radius-md);background:#fff2d8;color:#704b13}label{display:grid;gap:.35rem;font-size:.78rem;font-weight:700}textarea{min-height:5.5rem;resize:none;border:1px solid var(--color-border);border-radius:var(--radius-md);padding:.7rem;background:#fbfaf5;font:400 .78rem/1.5 var(--font-mono,monospace);overflow-wrap:anywhere}.error{color:var(--color-danger)}@media(max-width:34rem){.overlay{padding:0;align-items:flex-end}.dialog{border-radius:var(--radius-lg) var(--radius-lg) 0 0}}</style>
